    //Checks whether the target is a child node.
    checkParentExist(target) {
        let objBehind = target;
        while (this.diagram.nameTable[`${objBehind}`].parentId) {
            objBehind = this.diagram.nameTable[`${objBehind}`].parentId;
        }
        return objBehind;
    }
