        writer.writeAttributeString(null, 'FillStyle', null, '3');
        writer.writeAttributeString(null, 'TextStyle', null, '3');
        writer.writeStartElement(null, 'Cell', null);
        writer.writeAttributeString(null, 'N', null, 'PinX');
