            const transparency = 1 - node.style.opacity;
            writer.writeStartElement(null, 'Cell', null);
            writer.writeAttributeString(null, 'N', null, 'FillForegndTrans');
            writer.writeAttributeString(null, 'V', null, transparency.toString());
